//! The host resizers reproduce their references exactly: Pillow's
//! fixed-point bicubic on uint8 RGB byte for byte, and torch's antialiased
//! bilinear and bicubic (`F.interpolate(..., antialias=True,
//! align_corners=False)`) to float rounding, at odd sizes, downscaling and
//! upscaling. The constants come from `tools/goldens/imaging_resize_reference.py`
//! (Pillow 11.3, torch 2.0.1) over the same fixture image.

use imaging::host::{resize_aa_planar, resize_bicubic_pil, AaFilter};
use imaging::Rgb8;

const W: usize = 7;
const H: usize = 5;

/// `(37x + 11y + 53c) mod 256`, the reference script's fixture.
fn fixture() -> Rgb8 {
    let px = (0..H).flat_map(|y| (0..W).flat_map(move |x| (0..3).map(move |c| ((37 * x + 11 * y + 53 * c) % 256) as u8))).collect();
    Rgb8 { w: W as u32, h: H as u32, px }
}

/// The fixture as planar `[3, H, W]` floats in `0..=1`.
fn planar() -> Vec<f32> {
    let img = fixture();
    (0..3).flat_map(|c| (0..H * W).map(move |i| (c, i))).map(|(c, i)| img.px[i * 3 + c] as f32 / 255.0).collect()
}

#[test]
fn pil_bicubic_is_byte_exact() {
    for (w, h, want) in [(3usize, 4usize, &PIL_BICUBIC_3X4[..]), (11, 9, &PIL_BICUBIC_11X9[..])] {
        let got = resize_bicubic_pil(&fixture(), w, h);
        assert_eq!((got.w as usize, got.h as usize), (w, h));
        assert_eq!(got.px, want, "{w}x{h}");
    }
}

#[test]
fn torch_antialiased_resizes_match_to_float_rounding() {
    let cases = [
        (AaFilter::Bilinear, 3usize, 4usize, &TORCH_BILINEAR_AA_3X4[..]),
        (AaFilter::Bilinear, 11, 9, &TORCH_BILINEAR_AA_11X9[..]),
        (AaFilter::Bicubic, 3, 4, &TORCH_BICUBIC_AA_3X4[..]),
        (AaFilter::Bicubic, 11, 9, &TORCH_BICUBIC_AA_11X9[..]),
    ];
    let x = planar();
    for (filter, w, h, want) in cases {
        let got = resize_aa_planar(&x, 3, H, W, h, w, filter);
        let worst = got.iter().zip(want).map(|(a, b)| (a - b).abs()).fold(0.0f32, f32::max);
        assert!(worst < 1e-6, "{filter:?} {w}x{h}: max |diff| {worst}");
    }
}

